import pickle,re,collections
r=pickle.load(open('/tmp/r2tmp-701bbamz/claude-1000/cases2.pkl','rb'))
cases=[]
for x in r:
    if x['mode']=='blank': 
        if x['file']=='ord_PSD_020823.txt' and x['page']==190:
            cases.append((x['file'],x['page'],''))
        continue
    if x['file']=='ord_PSD_042121.txt' and x['page']==155:
        cases.append((x['file'],x['page'],'Total Development Systems, LLC')); continue
    if x['mode']=='std': cases.append((x['file'],x['page'],x['resp']))
    elif x['mode']=='alt': cases.append((x['file'],x['page'],x['resp']))
    else: print('UNRESOLVED',x['file'],x['page'])
print('cases',len(cases))
UT=["centerpoint","northern indiana public service","nipsco","citizens gas","citizens energy","vectren","indiana american water","ohio valley gas","american electric power","duke energy","community natural gas","midwest natural gas","frontier communications"]
def is_util(n): 
    s=n.strip().lower().lstrip(' ')
    return any(s.startswith(u) for u in UT)
SUF={'inc','llc','co','corp','corporation','company'}
def norm(n):
    s=n.lower()
    s=''.join(c for c in s if c.isalpha() or c.isdigit() or c==' ')
    s=re.sub(' +',' ',s).strip()
    w=s.split(' ')
    if len(w)>0 and w[-1] in SUF:
        s=' '.join(w[:-1])
    return s
nonu=[c for c in cases if not is_util(c[2] or '')]
print('utility',len(cases)-len(nonu),'nonutility',len(nonu))
cnt=collections.Counter(norm(c[2]) for c in nonu)
big={k:v for k,v in cnt.items() if v>=5}
tot=sum(big.values())
print('distinct normalized',len(cnt),'>=5 groups',len(big),'cases in them',tot,'pct',round(100*tot/len(nonu),1))
for k,v in sorted(big.items(),key=lambda x:-x[1]): print(v,repr(k))
print('blank-name cases', cnt.get('',0))
EOF
